        public static object Fresh(string chunk)
        {
            var env = new LuaEnv();
            try
            {
                return env.DoString(chunk)[0];
            }
            finally
            {
                // Release the delegates the chunk made so Dispose accepts the env.
                env.FullGc();
                GC.Collect();
                GC.WaitForPendingFinalizers();
                env.Tick();
                env.Dispose();
            }
        }

