    // Inherited from upstream, not reported there: xlua.private_accessible
    // wrapped each method once per non-public method of the same name (an
    // Enumerable.Join on the name), so Pick below held every overload twice,
    // and Single, whose static and instance forms share a name, lost the
    // unchecked call that a method with one overload gets.
    public class PrivateOverloads
    {
        public string Pick(double x)
        {
            return "double";
        }

        private string Pick(bool b)
        {
            return "bool";
        }

        private string Pick(PrivateOverloads other)
        {
            return "object";
        }

        // One instance and one static overload: each is called without an
        // argument check, so a number converts to the string, as it does for
        // a public method with one overload.
        private string Single(string s)
        {
            return "s:" + s;
        }

        private static string Single(int i, int j)
        {
            return "ij";
        }

        static object Field(object o, string name)
        {
            return o.GetType().GetField(name, System.Reflection.BindingFlags.Instance |
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public).GetValue(o);
        }

        // The overloads of each wrapper named `name` that private_accessible
        // builds in a fresh LuaEnv: "<count> <parameter types>,..." per
        // wrapper, the wrappers sorted and joined with "|".
        public static string Overloads(string name)
        {
            var env = new LuaEnv();
            try
            {
                // Load the type first: without emitted or generated wrappers its public
                // members get reflection wrappers too, and those are not counted here.
                env.DoString("local t = CS.Upstream.PrivateOverloads");
                var functions = (System.Collections.IList)Field(Field(env, "translator"), "fix_cs_functions");
                int before = functions.Count;
                env.DoString("xlua.private_accessible(CS.Upstream.PrivateOverloads)");
                var wraps = new System.Collections.Generic.List<string>();
                for (int i = before; i < functions.Count; i++)
                {
                    var wrap = ((Delegate)functions[i]).Target as MethodWrap;
                    if (wrap == null || (string)Field(wrap, "methodName") != name)
                    {
                        continue;
                    }
                    var overloads = (System.Collections.IList)Field(wrap, "overloads");
                    var signatures = new System.Collections.Generic.SortedSet<string>();
                    foreach (var overload in overloads)
                    {
                        var parameters = ((System.Reflection.MethodBase)Field(overload, "method")).GetParameters();
                        var types = new string[parameters.Length];
                        for (int j = 0; j < parameters.Length; j++)
                        {
                            types[j] = parameters[j].ParameterType.Name;
                        }
                        signatures.Add(string.Join(";", types));
                    }
                    wraps.Add(overloads.Count + " " + string.Join(",", new System.Collections.Generic.List<string>(signatures).ToArray()));
                }
                wraps.Sort(string.CompareOrdinal);
                return string.Join("|", wraps.ToArray());
            }
            finally
            {
                env.Dispose();
            }
        }
    }

    // Tencent/xLua#1118: without generated code, every LuaEnv emitted its
    // wrappers and bridges into a new XLuaCodeEmit dynamic assembly, which
    // .NET never unloads, so with domain reload disabled they added up. The
    // emitted types are now shared by every env in the process. The classes
    // below are not in LuaCallCSharp: the reflection suite emits wrappers
    // for them, the generated-code suites reflect them.
    [CSharpCallLua]
    public delegate int EmitCacheFunc(int x);

    [CSharpCallLua]
    public interface IEmitCacheCounter
    {
        int Add(int x);
        int Total { get; set; }
    }

    public class EmitCacheTarget
    {
        public int Value;

        public EmitCacheTarget(int value)
        {
            Value = value;
        }

        public int Twice()
        {
            return Value * 2;
        }

        public static int Square(int x)
        {
            return x * x;
        }
    }

    // Loaded first by envs on other threads, at the same time where envs may
    // run concurrently.
    public class EmitCacheThreadTarget
    {
        public static int Cube(int x)
        {
            return x * x * x;
        }
    }

    public static class EmitCache
    {
        // The XLuaCodeEmit dynamic assemblies loaded in this process.
        public static int Assemblies()
        {
            int count = 0;
            foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (assembly.IsDynamic && assembly.GetName().Name == "XLuaCodeEmit")
                {
                    count++;
                }
            }
            return count;
        }

        // How many there are once an env exists: one while CodeEmit is
        // compiled in (ObjectTranslator.ce) and no generated delegate bridges
        // turn it off (DelegateBridge.Gen_Flag), otherwise none.
        public static int Expected()
        {
            bool compiled = typeof(ObjectTranslator).GetField("ce",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic) != null;
            return compiled && !DelegateBridge.Gen_Flag ? 1 : 0;
        }

        const string Chunk = @"
            function emit_cache_f(x)
                local o = CS.Upstream.EmitCacheTarget(x)
                o.Value = o.Value + 1
                return o:Twice() + CS.Upstream.EmitCacheTarget.Square(x)
            end
            emit_cache_counter = { Total = 0 }
            function emit_cache_counter:Add(x)
                self.Total = self.Total + x
                return self.Total
            end
        ";

        // A delegate and an interface bridge to Lua, made from a Lua call:
        // the delegate must be unreachable when the env is disposed, and one
        // made in a C# frame can stay visible to Mono's conservative stack
        // scan, which then sees a C# callback left (StackRoom.Fresh does the
        // same).
        internal static int Use(LuaEnv env, int seed)
        {
            env.DoString(Chunk);
            return Convert.ToInt32(env.DoString("return CS.Upstream.EmitCache.Call(emit_cache_f, emit_cache_counter, " + seed + ")")[0]);
        }

        public static int Call(EmitCacheFunc f, IEmitCacheCounter counter, int seed)
        {
            int r = f(seed) * 1000 + counter.Add(seed) * 10 + counter.Add(1);
            counter.Total = 100;
            r += counter.Total * 100000;
            ((IDisposable)counter).Dispose();
            return r;
        }

        // What Use returns: f(s) = 2 (s + 1) + s^2, Add gives s, then s + 1,
        // and Total reads back 100.
        internal static int Want(int seed)
        {
            return 10000000 + (2 * (seed + 1) + seed * seed) * 1000 + seed * 10 + seed + 1;
        }

        internal static string Check(string what, int got, int want)
        {
            return got == want ? "" : what + ": " + got + " != " + want + "; ";
        }

        // n envs one after another, each disposed before the next.
        public static string Sequential(int n)
        {
            string errors = "";
            for (int i = 1; i <= n; i++)
            {
                var env = new LuaEnv();
                try
                {
                    errors += Check("env " + i, Use(env, i), Want(i));
                }
                finally
                {
                    env.Dispose();
                }
                errors += Check("XLuaCodeEmit assemblies after env " + i, Assemblies(), Expected());
            }
            return errors;
        }

        // Two envs alive at once, used in turn.
        public static string TwoAlive()
        {
            string errors = "";
            var a = new LuaEnv();
            var b = new LuaEnv();
            try
            {
                errors += Check("a", Use(a, 3), Want(3));
                errors += Check("b", Use(b, 4), Want(4));
                errors += Check("a again", Use(a, 5), Want(5));
                errors += Check("XLuaCodeEmit assemblies", Assemblies(), Expected());
            }
            finally
            {
                a.Dispose();
                b.Dispose();
            }
            return errors;
        }

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static string OnThread(int seed)
        {
            var env = new LuaEnv();
            try
            {
                object cube = env.DoString("return CS.Upstream.EmitCacheThreadTarget.Cube(3)")[0];
                return Check("thread " + seed + " cube", Convert.ToInt32(cube), 27)
                    + Check("thread " + seed, Use(env, seed), Want(seed));
            }
            finally
            {
                env.Dispose();
            }
        }

        // n envs, each created, used and disposed on a thread of its own. The
        // threads run at the same time where envs may (THREAD_SAFE or
        // HOTFIX_ENABLE lock ObjectTranslatorPool), otherwise one after another.
        public static string Threads(int n)
        {
            var results = new string[n];
            var threads = new System.Threading.Thread[n];
            for (int i = 0; i < n; i++)
            {
                int k = i;
                threads[i] = new System.Threading.Thread(() =>
                {
                    try
                    {
                        results[k] = OnThread(k + 1);
                    }
                    catch (Exception e)
                    {
                        results[k] = "thread " + (k + 1) + ": " + e + "; ";
                    }
                });
            }
#if THREAD_SAFE || HOTFIX_ENABLE
            for (int i = 0; i < n; i++)
            {
                threads[i].Start();
            }
            for (int i = 0; i < n; i++)
            {
                threads[i].Join();
            }
#else
            for (int i = 0; i < n; i++)
            {
                threads[i].Start();
                threads[i].Join();
            }
#endif
            return string.Join("", results) + Check("XLuaCodeEmit assemblies after the threads", Assemblies(), Expected());
        }
    }

    // Without generated code each LuaEnv scanned every loaded type for
    // [CSharpCallLua] (ObjectTranslator.initCSharpCallLua), most of its
    // creation time. The scan is now kept for the process
    // (ObjectTranslator.CSharpCallLuaScan) while the loaded assemblies stay
    // the same, and made again once one is loaded.
    public static class EnvScanCache
    {
        // ObjectTranslator.CSharpCallLuaScan.scans: how many times the loaded
        // types were scanned.
        static System.Reflection.FieldInfo counter()
        {
            var scan = typeof(ObjectTranslator).GetNestedType("CSharpCallLuaScan", System.Reflection.BindingFlags.NonPublic);
            return scan == null ? null : scan.GetField("scans", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
        }

        const string NoCounter = "no scan counter (ObjectTranslator.CSharpCallLuaScan.scans): every LuaEnv scans the loaded types; ";

        // Whether the scan includes a dynamic assembly, which it cannot keep
        // (a dynamic assembly can gain types): then every env scans again.
        // The scan leaves out assemblies whose ManifestModule is a
        // ModuleBuilder and XLuaCodeEmit. On Mono that is every
        // AssemblyBuilder; the .NET Framework lists the runtime assembly behind
        // a builder, so a builder made by the program (defineLater below)
        // turns the cache off there (docs/research/windows-host.md).
        static bool scansDynamic()
        {
            foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (assembly.IsDynamic && !(assembly.ManifestModule is System.Reflection.Emit.ModuleBuilder)
                    && assembly.GetName().Name != "XLuaCodeEmit")
                {
                    return true;
                }
            }
            return false;
        }

        // n envs in a row with the same assemblies loaded scan once at most,
        // and each still bridges a CSharpCallLua delegate and interface.
        // Nothing scans with generated delegate bridges or without CodeEmit.
        public static string Reused(int n)
        {
            if (EmitCache.Expected() == 0) return "";
            var scans = counter();
            if (scans == null) return NoCounter;
            // Brings the scan up to date with the assemblies loaded so far.
            new LuaEnv().Dispose();
            int before = (int)scans.GetValue(null);
            string errors = "";
            for (int i = 1; i <= n; i++)
            {
                var env = new LuaEnv();
                try
                {
                    errors += EmitCache.Check("env " + i, EmitCache.Use(env, i), EmitCache.Want(i));
                }
                finally
                {
                    env.Dispose();
                }
            }
            return errors + EmitCache.Check("scans for " + n + " envs", (int)scans.GetValue(null) - before, scansDynamic() ? n : 0);
        }

// Mono only: .NET 5 and later have no AssemblyBuilderAccess.Save
// (coverage_cs_dotnet.py runs this suite on .NET).
#if XLUA_GENERAL && !NET5_0_OR_GREATER
        static int later = 0;

        // A [CSharpCallLua] interface in an assembly loaded now, from a file
        // (a static assembly; the scan leaves out dynamic ones).
        static Type defineLater()
        {
            later++;
            var name = new System.Reflection.AssemblyName("XLuaEnvScanLater" + later + "_" + System.Diagnostics.Process.GetCurrentProcess().Id);
            string dir = System.IO.Path.GetTempPath();
            string file = name.Name + ".dll";
            var builder = AppDomain.CurrentDomain.DefineDynamicAssembly(name, System.Reflection.Emit.AssemblyBuilderAccess.Save, dir);
            var module = builder.DefineDynamicModule(name.Name, file);
            var type = module.DefineType("Upstream.EnvScanLater" + later + ".ITwice",
                System.Reflection.TypeAttributes.Public | System.Reflection.TypeAttributes.Interface | System.Reflection.TypeAttributes.Abstract);
            type.SetCustomAttribute(new System.Reflection.Emit.CustomAttributeBuilder(
                typeof(CSharpCallLuaAttribute).GetConstructor(Type.EmptyTypes), new object[0]));
            type.DefineMethod("Twice", System.Reflection.MethodAttributes.Public | System.Reflection.MethodAttributes.Abstract
                | System.Reflection.MethodAttributes.Virtual | System.Reflection.MethodAttributes.HideBySig
                | System.Reflection.MethodAttributes.NewSlot, typeof(int), new Type[] { typeof(int) });
            type.CreateType();
            builder.Save(file);
            string path = System.IO.Path.Combine(dir, file);
            var loaded = System.Reflection.Assembly.LoadFrom(path);
            try
            {
                System.IO.File.Delete(path);
            }
            catch (Exception)
            {
            }
            return loaded.GetType(type.FullName, true);
        }

        // A Lua table as the interface, in a new env (the interface bridge
        // needs the interface in the env's CSharpCallLua list).
        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static string twiceInNewEnv(Type iface)
        {
            var env = new LuaEnv();
            try
            {
                var table = (LuaTable)env.DoString("return { Twice = function(self, x) return x * 2 end }")[0];
                object bridge;
                try
                {
                    bridge = typeof(LuaTable).GetMethod("Cast").MakeGenericMethod(iface).Invoke(table, null);
                }
                catch (System.Reflection.TargetInvocationException e)
                {
                    table.Dispose();
                    return iface + " as CSharpCallLua: " + e.InnerException.Message + "; ";
                }
                object twice = iface.GetMethod("Twice").Invoke(bridge, new object[] { 21 });
                ((IDisposable)bridge).Dispose();
                table.Dispose();
                return EmitCache.Check(iface + ".Twice(21)", Convert.ToInt32(twice), 42);
            }
            finally
            {
                env.Dispose();
            }
        }

        // An env after an assembly is loaded scans again and finds its
        // CSharpCallLua types; the next env reuses that scan.
        public static string LaterAssembly()
        {
            if (EmitCache.Expected() == 0) return "";
            var scans = counter();
            if (scans == null) return NoCounter;
            new LuaEnv().Dispose();
            int before = (int)scans.GetValue(null);
            Type iface = defineLater();
            string errors = twiceInNewEnv(iface);
            int after = (int)scans.GetValue(null);
            if (after == before) errors += "no scan after " + iface.Assembly.GetName().Name + " was loaded; ";
            errors += twiceInNewEnv(iface);
            return errors + EmitCache.Check("scans for the env after that", (int)scans.GetValue(null), after + (scansDynamic() ? 1 : 0));
        }
#else
        public static string LaterAssembly()
        {
            return "";
        }
#endif
    }

    // An internal type: every mode wraps it by reflection (CodeEmit only
    // emits public types, and nothing generates a wrapper for it).
    internal class ReflectedShape
    {
        public int Field = 1;
        public int Prop { get; set; }
        readonly System.Collections.Generic.Dictionary<int, int> items = new System.Collections.Generic.Dictionary<int, int>();
        public int this[int i]
        {
            get { int v; return items.TryGetValue(i, out v) ? v : -1; }
            set { items[i] = value; }
        }
        public string Pick(int x) { return "int" + x; }
        public string Pick(string x) { return "string:" + x; }
        public string Optional(int a, int b = 40) { return (a + b).ToString(); }
        public static ReflectedShape operator +(ReflectedShape a, ReflectedShape b)
        {
            return new ReflectedShape { Field = a.Field + b.Field, Prop = a.Prop + b.Prop };
        }
    }

    // Every LuaEnv wraps System.RuntimeType by reflection when it is created
    // (the Type object that ObjectTranslator.CreateArrayMetatable pushes),
    // three quarters of its creation time with generated code. What
    // reflection finds for a type is now kept for the process
    // (Utils.ReflectionMembers); each env still makes its own wrappers.
    public static class EnvReflectionCache
    {
        public static object Make()
        {
            return new ReflectedShape();
        }

        // Utils.ReflectionMembers.builds: how many times members were made.
        static System.Reflection.FieldInfo counter()
        {
            var members = typeof(Utils).GetNestedType("ReflectionMembers", System.Reflection.BindingFlags.NonPublic);
            return members == null ? null : members.GetField("builds", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic);
        }

        const string Chunk = @"
            local T = CS.Upstream.EnvReflectionCache
            local o = T.Make()
            o.Field = 5
            o.Prop = 6
            o[2] = 7
            local s = o + o
            local t = typeof(CS.System.Int32)
            return table.concat({ o.Field, o.Prop, o[2], o[3], o:Pick(1), o:Pick('a'), o:Optional(2), s.Field, s.Prop,
                t.FullName, tostring(t.IsValueType), tostring(t:IsAssignableFrom(typeof(CS.System.Int32))),
                typeof(CS.System.Array):GetType().Name }, ',')";

        const string Want = "5,6,7,-1,int1,string:a,42,10,12,System.Int32,true,true,";

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static string run(string what)
        {
            var env = new LuaEnv();
            try
            {
                string got = (string)env.DoString(Chunk)[0];
                // The last item is the runtime's class of a Type object
                // (RuntimeType on Mono and .NET).
                return got.StartsWith(Want) && got.Length > Want.Length ? "" : what + ": " + got + "; ";
            }
            finally
            {
                env.Dispose();
            }
        }

        // n envs in a row make no members: the first env of the suite made
        // those of RuntimeType and ReflectedShape, and every env binds the
        // same members.
        public static string Reused(int n)
        {
            var builds = counter();
            if (builds == null) return "no counter (Utils.ReflectionMembers.builds): every LuaEnv reflects over the types it wraps; ";
            string errors = run("env 0");
            int before = (int)builds.GetValue(null);
            for (int i = 1; i <= n; i++)
            {
                errors += run("env " + i);
            }
            return errors + EmitCache.Check("members made for " + n + " envs", (int)builds.GetValue(null) - before, 0);
        }

        // Envs on several threads share the members (THREAD_SAFE; one after
        // the other without it, as EmitCache.Threads).
        public static string Threads(int n)
        {
            var results = new string[n];
            var threads = new System.Threading.Thread[n];
            for (int i = 0; i < n; i++)
            {
                int k = i;
                threads[i] = new System.Threading.Thread(() =>
                {
                    try
                    {
                        string r = "";
                        for (int j = 0; j < 5; j++) r += run("thread " + (k + 1) + " env " + j);
                        results[k] = r;
                    }
                    catch (Exception e)
                    {
                        results[k] = "thread " + (k + 1) + ": " + e + "; ";
                    }
                });
            }
#if THREAD_SAFE || HOTFIX_ENABLE
            for (int i = 0; i < n; i++)
            {
                threads[i].Start();
            }
            for (int i = 0; i < n; i++)
            {
                threads[i].Join();
            }
#else
            for (int i = 0; i < n; i++)
            {
                threads[i].Start();
                threads[i].Join();
            }
#endif
            return string.Join("", results);
        }
    }

    // Tencent/xLua#731: computed configuration lists can hold types that
    // generated code cannot name: a delegate and a List<T> over an anonymous
    // type (from a lambda or a LINQ query) and a delegate over a protected
    // nested type. Generate Code wrote them into DelegatesGensBridge and a
    // class wrapper, which then did not compile; it now leaves them out. The
    // Func<int, int> next to them keeps its bridge.
    public class ProtectedHolder
    {
        protected class Hidden
        {
        }

        public static Type HiddenAction()
        {
            return typeof(Action<Hidden>);
        }
    }

    public static class UnnameableConfig
    {
        static Type FuncOf<T>(Func<T> f)
        {
            return typeof(Func<T>);
        }

        static Type ListOf<T>(Func<T> f)
        {
            return typeof(List<T>);
        }

        [CSharpCallLua]
        public static List<Type> Delegates
        {
            get { return new List<Type> { FuncOf(() => new { A = 1 }), ProtectedHolder.HiddenAction(), typeof(Func<int, int>) }; }
        }

        [LuaCallCSharp]
        public static List<Type> Classes
        {
            get { return new List<Type> { ListOf(() => new { B = 2 }) }; }
        }
    }

    // Tencent/xLua#924 (also #1140): a generic extension method with a
    // parameter of a generic type over its type parameter, such as
    // ApplySelfTo<T>(this T self, Action<T> f) where T : UnityEngine.Object.
    // Generate Code stopped in TemplateCommon ("attempt to index a nil value
    // (field 'FullName')"); generated code now leaves the method out, as it
    // does for other generic methods with such parameters. Reflection and
    // emitted wrappers call it with T = the constraint.
    [LuaCallCSharp]
    public class ApplyTarget
    {
        public int Value;
    }

    [LuaCallCSharp]
    public static class ApplyExtensions
    {
        public static T ApplySelfTo<T>(this T self, Action<T> f) where T : ApplyTarget
        {
            f(self);
            return self;
        }

        public static int Twice(this ApplyTarget self)
        {
            return self.Value * 2;
        }
    }

    // Tencent/xLua#1081 (and #1179): outside Unity, .NET Framework and .NET on
    // Windows marshal string parameters in the ANSI code page, so a chunk name,
    // a path for GetInPath/SetInPath or an error message with other characters
    // reached Lua garbled. The imports now pass UTF-8 there, as Unity's runtimes
    // do. (Mono and .NET on macOS and Linux marshal UTF-8 already, so this
    // passes there with or without the change.)
    public static class Utf8Marshal
    {
        public static string Check()
        {
            string r = "";
            using (var env = new LuaEnv())
            {
                var source = (string)env.DoString("return debug.getinfo(1, 'S').source", "@\u811a\u672c/\u4e2d\u6587.lua")[0];
                if (source != "@\u811a\u672c/\u4e2d\u6587.lua") r += "chunk name " + source + "; ";
                env.DoString("t = { ['\u952e'] = '\u503c' }");
                var value = env.Global.GetInPath<string>("t.\u952e");
                if (value != "\u503c") r += "GetInPath " + value + "; ";
                env.Global.SetInPath("t.\u65b0", "\u65b0\u503c");
                var set = (string)env.DoString("return t['\u65b0']")[0];
                if (set != "\u65b0\u503c") r += "SetInPath " + set + "; ";
            }
            return r;
        }

        public static void Throw()
        {
            throw new Exception("\u4e2d\u6587\u9519\u8bef");
        }
    }

    // Tencent/xLua#741: LuaBase finalizers queue their references for the next
    // LuaEnv.Tick. The queue was a locked Queue<T>, which a finalizer running on
    // the same thread while it grew (WebGL runs finalizers when an allocation
    // collects) entered again and broke; it is now a lock-free list. Every
    // reference a finalizer queues is still released at the next Tick.
    public static class GCQueue
    {
        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static void Leak(LuaEnv env, int n)
        {
            var make = (LuaFunction)env.DoString("return function(i) local t = {} weak[i] = t return t end")[0];
            for (int i = 1; i <= n; i++)
            {
                make.Call(i);
            }
            make.Dispose();
        }

        public static string Check(int n)
        {
            using (var env = new LuaEnv())
            {
                env.DoString("weak = setmetatable({}, { __mode = 'v' })");
                Leak(env, n);
                GC.Collect();
                GC.WaitForPendingFinalizers();
                env.Tick();
                int left = Convert.ToInt32(env.DoString("collectgarbage() collectgarbage() local c = 0 for _ in pairs(weak) do c = c + 1 end return c")[0]);
                // Mono scans the stack conservatively and may keep the last one or two.
                return left <= 2 ? "" : left + " of " + n + " tables are still referenced after Tick";
            }
        }
    }

    // Tencent/xLua#918: a Lua table where a UnityEngine.Object type is
