        }

        public static string Packed(StrictPacked p)
        {
            return StrictStructs.Packed(p);
        }
    }

    // Tencent/xLua#1182: require passes the loader data, the module's path, to
    // the module and (Lua 5.4 and 5.5) returns it as its second value, for
    // xLua's searchers too. Each check runs in a new LuaEnv with a custom
    // loader that sets the path to "virtual/<name>.lua" and a builtin module.
    public static class RequireData
    {
        static byte[] Load(ref string path)
        {
            if (path != "vmod") return null;
            path = "virtual/" + path + ".lua";
            return System.Text.Encoding.UTF8.GetBytes(
                "return { n = select('#', ...), name = (...), data = select(2, ...) }");
        }

        // The builtin module is the number of arguments its loader got.
        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int Builtin(IntPtr L)
        {
            XLua.LuaDLL.Lua.lua_pushnumber(L, XLua.LuaDLL.Lua.lua_gettop(L));
            return 1;
        }

        // Runs chunk in a new LuaEnv with the custom loader of "vmod" and the
        // builtin module "vbuiltin"; returns its first result as a string.
        public static string Run(string chunk)
        {
            var env = new LuaEnv();
            try
            {
                env.AddLoader(Load);
                env.AddBuildin("vbuiltin", Builtin);
                return Convert.ToString(env.DoString(chunk)[0]);
            }
            finally
            {
                env.Dispose();
            }
        }
    }

    // Tencent/xLua#999: a delegate or interface bridge that outlives its LuaEnv.
    // LuaEnv.Dispose refuses while a delegate bridge is reachable, but a bridge
    // that its holder disposed (code that frees Lua callbacks eagerly through
    // Delegate.Target), one that a finalizer resurrected after its weak entry was
    // cleared, and every interface bridge (Dispose does not track them) stay
    // callable after Dispose. Generated delegate and hotfix bridges then passed a
    // NULL state to pcall_prepare and the process crashed; every bridge now throws
    // ObjectDisposedException. Each check runs in a LuaEnv of its own; the bridges
    // are generated in the --source-gen runs and emitted or reflected otherwise.
    public static class DisposedEnvBridges
    {
        static string Expect(string what, Action call)
        {
            try
            {
                call();
                return what + ": no exception after LuaEnv.Dispose; ";
            }
            catch (ObjectDisposedException)
            {
                return "";
            }
            catch (Exception e)
            {
                return what + ": " + e.GetType().Name + " instead of ObjectDisposedException; ";
            }
        }

        public static string Check()
        {
            var env = new LuaEnv();
            env.DoString("function inc(x) return x + 1 end function noop() end t = { Answer = function(self, n) return n * 2 end }");
            var inc = env.Global.Get<Func<int, int>>("inc");
            var noop = env.Global.Get<Action>("noop");
            var callback = env.Global.Get<Coverage.MultiListedCallback>("inc");
            var iface = env.Global.Get<Coverage.IMultiListed>("t");
            var function = env.Global.Get<LuaFunction>("inc");
            var table = env.Global.Get<LuaTable>("t");
            if (inc(1) != 2 || callback(2) != 3 || iface.Answer(3) != 6) return "the bridges do not work before Dispose";
            noop();
            // Released by their holder: Dispose no longer sees them.
            ((IDisposable)inc.Target).Dispose();
            ((IDisposable)noop.Target).Dispose();
            ((IDisposable)callback.Target).Dispose();
            env.Dispose();
            return Expect("Func<int, int>", () => inc(1))
                + Expect("Action", () => noop())
                + Expect("MultiListedCallback", () => callback(1))
                + Expect("interface bridge", () => iface.Answer(1))
                + Expect("LuaFunction.Call", () => function.Call(1))
                + Expect("LuaFunction.Cast", () => function.Cast<Action>())
                + Expect("LuaTable.Get", () => table.Get<int>("x"))
                + Expect("LuaTable.Set", () => table.Set("x", 1))
                + Expect("LuaEnv.DoString", () => env.DoString("return 1"))
                + Expect("LuaEnv.Global", () => { var g = env.Global; g.Get<int>("x"); })
                + Expect("LuaEnv.Tick", () => env.Tick())
                + Expect("LuaEnv.Alias", () => env.Alias(typeof(int), "Int32Alias"));
        }

        // A finalizer that keeps the delegate it held: its holder becomes
        // unreachable, the GC clears the bridge's weak entry and runs both
        // finalizers, and the delegate lives on in Kept.
        sealed class Holder
        {
            public Action Callback;
            ~Holder() { Kept = Callback; }
        }

        static Action Kept;

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static void Hold(LuaEnv env)
        {
            new Holder { Callback = env.Global.Get<Action>("noop") };
        }

        public static string CheckResurrected()
        {
            var env = new LuaEnv();
            env.DoString("function noop() end");
            Kept = null;
            // The holder is made on a thread that then ends, so no stack keeps it:
            // Mono scans stacks conservatively. The env goes to that thread and back.
            var maker = new System.Threading.Thread(() => { env.SetOwnerThread(); Hold(env); });
            maker.Start();
            maker.Join();
            env.SetOwnerThread();
            GC.Collect();
            GC.WaitForPendingFinalizers();
            if (Kept == null) return "the holder was not finalized";
            try
            {
                env.Dispose();
            }
            catch (InvalidOperationException e)
            {
                Kept = null;
                return "Dispose refused: " + e.Message;
            }
            var kept = Kept;
            Kept = null;
            return Expect("resurrected Action", () => kept());
        }

        // LuaEnv.Dispose() a second time does nothing (IDisposable), as
        // Dispose(bool) already did; it used to throw from FullGc.
        public static string DisposeTwice()
        {
            var env = new LuaEnv();
            env.Dispose();
            try
            {
                env.Dispose();
                env.Dispose(true);
                return "";
            }
            catch (Exception e)
            {
                return "second Dispose threw " + e.GetType().Name + ": " + e.Message;
            }
        }
    }

    // Two threads in one LuaEnv, or a C# finalizer that calls Lua, corrupted the
    // Lua heap and crashed (docs/research/crash-inventory.md, items 5 and 6).
    // With the bridge checks (XLUA_GENERAL here), and without THREAD_SAFE and
    // HOTFIX_ENABLE, which lock every entry, a use from a thread that does not
    // own the env throws InvalidOperationException, and SetOwnerThread hands the
    // env over. Without the check the same calls run, one thread at a time.
    // Each check runs in a LuaEnv of its own; the delegate and interface bridges
    // are generated in the --source-gen runs and emitted or reflected otherwise.
    public static class OwnerThread
    {
        public static bool Checked()
        {
#if XLUA_BRIDGE_CHECKS && !THREAD_SAFE && !HOTFIX_ENABLE
            return true;
#else
            return false;
#endif
        }

        // Runs body on a thread of its own and returns what it threw.
        static Exception OnOtherThread(Action body)
        {
            Exception seen = null;
            var thread = new System.Threading.Thread(() =>
            {
                try
                {
                    body();
                }
                catch (Exception e)
                {
                    seen = e;
                }
            });
            thread.Start();
            thread.Join();
            return seen;
        }

        static string Refused(string what, int owner, Action body)
        {
            Exception e = OnOtherThread(body);
            if (!Checked())
            {
                return e == null ? "" : what + ": " + e.GetType().Name + " without the check: " + e.Message + "; ";
            }
            if (e == null || e.GetType() != typeof(InvalidOperationException))
            {
                return what + ": " + (e == null ? "no exception" : e.GetType().Name + ": " + e.Message) + " on another thread; ";
            }
            foreach (string part in new[] { "belongs to thread " + owner + " but is used from thread ", "SetOwnerThread()", "THREAD_SAFE", "finalizer" })
            {
                if (!e.Message.Contains(part)) return what + ": the message lacks \"" + part + "\": " + e.Message + "; ";
            }
            return "";
        }

        public static string Check()
        {
            int owner = Environment.CurrentManagedThreadId;
            var env = new LuaEnv();
            env.DoString("function inc(x) return x + 1 end t = { Answer = function(self, n) return n * 2 end }");
            var inc = env.Global.Get<Func<int, int>>("inc");
            var callback = env.Global.Get<Coverage.MultiListedCallback>("inc");
            var iface = env.Global.Get<Coverage.IMultiListed>("t");
            var function = env.Global.Get<LuaFunction>("inc");
            var table = env.Global.Get<LuaTable>("t");
            string r = Refused("Func<int, int>", owner, () => inc(1))
                + Refused("MultiListedCallback", owner, () => callback(1))
                + Refused("interface bridge", owner, () => iface.Answer(1))
                + Refused("LuaFunction.Call", owner, () => function.Call(1))
                + Refused("LuaTable.Get", owner, () => table.Get<object>("x"))
                + Refused("LuaEnv.DoString", owner, () => env.DoString("return 1"))
                + Refused("LuaEnv.NewTable", owner, () => env.NewTable());
            if (Checked())
            {
                // Refused before it closes anything (without the check Dispose would work).
                r += Refused("LuaEnv.Dispose", owner, () => env.Dispose());
            }
            // The owner still uses the env, and the refusals left the stack as it was.
            if (inc(1) != 2 || callback(2) != 3 || iface.Answer(3) != 6 || Convert.ToInt32(function.Call(4)[0]) != 5)
            {
                r += "the owner cannot use the env after the refusals; ";
            }
            // The hand-off: another thread takes the env over, then the owner takes it back.
            int onWorker = 0;
            Exception handOff = OnOtherThread(() =>
            {
                env.SetOwnerThread();
                onWorker = inc(41) + iface.Answer(1) + Convert.ToInt32(env.DoString("return 1")[0]);
            });
            if (handOff != null || onWorker != 45)
            {
                r += "SetOwnerThread on another thread: " + (handOff == null ? "got " + onWorker : handOff.Message) + "; ";
            }
            if (Checked())
            {
                try
                {
                    inc(1);
                    r += "the creator was not refused after the hand-off; ";
                }
                catch (InvalidOperationException)
                {
                }
            }
            env.SetOwnerThread();
            if (inc(1) != 2) r += "SetOwnerThread back on the creator; ";
            ((IDisposable)inc.Target).Dispose();
            ((IDisposable)callback.Target).Dispose();
            function.Dispose();
            table.Dispose();
            env.Dispose();
            return r;
        }

        sealed class CallsLuaWhenFinalized
        {
            public LuaFunction Function;
            public static Exception Seen;
            public static bool Ran;

            ~CallsLuaWhenFinalized()
            {
                try
                {
                    Function.Call(1);
                }
                catch (Exception e)
                {
                    Seen = e;
                }
                Ran = true;
            }
        }

        [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
        static void DropLuaObjects(LuaEnv env)
        {
            for (int i = 0; i < 50; i++)
            {
                env.NewTable();
                env.Global.Get<LuaFunction>("inc");
            }
        }

        // The finalizers of LuaTable, LuaFunction and the delegate bridges run on
        // the finalizer thread: they only queue the reference, and the owner's
        // next Tick releases it, so the check never sees them. A finalizer of the
        // user's that calls Lua is refused.
        public static string Finalizers()
        {
            var env = new LuaEnv();
            string r = "";
            try
            {
                env.DoString("function inc(x) return x + 1 end");
                // Made on a thread that then ends, so no stack keeps them (Mono scans
                // stacks conservatively); the env goes to that thread and back.
                Exception made = OnOtherThread(() =>
                {
                    env.SetOwnerThread();
                    DropLuaObjects(env);
                });
                env.SetOwnerThread();
                if (made != null) return "making the objects: " + made.Message;
                GC.Collect();
                GC.WaitForPendingFinalizers();
                var queue = typeof(LuaEnv).GetField("refQueue", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (queue.GetValue(env) == null) r += "no finalizer queued a release; ";
                env.Tick();
                if (queue.GetValue(env) != null) r += "Tick left releases in the queue; ";

                var function = env.Global.Get<LuaFunction>("inc");
                CallsLuaWhenFinalized.Seen = null;
                CallsLuaWhenFinalized.Ran = false;
                OnOtherThread(() => new CallsLuaWhenFinalized { Function = function });
                GC.Collect();
                GC.WaitForPendingFinalizers();
                Exception seen = CallsLuaWhenFinalized.Seen;
                if (!CallsLuaWhenFinalized.Ran)
                {
                    r += "the caller was not finalized; ";
                }
                else if (Checked() ? seen == null || seen.GetType() != typeof(InvalidOperationException) || !seen.Message.Contains("finalizer") : seen != null)
                {
                    r += "a call from a finalizer: " + (seen == null ? "no exception" : seen.GetType().Name + ": " + seen.Message) + "; ";
                }
                function.Dispose();
                if (Convert.ToInt32(env.DoString("return inc(1)")[0]) != 2) r += "the env does not work afterwards; ";
            }
            finally
            {
                env.Dispose();
            }
            return r;
        }

        // LuaOptions.CheckThread = false turns the check off for one env, and the
        // statistics and Interrupt work from any thread, as LuaScript's.
        public static string OptionsAndStatistics()
        {
            string r = "";
            var env = new LuaEnv(new LuaOptions { CheckThread = false });
            try
            {
                Exception e = OnOtherThread(() => env.DoString("x = 1"));
                if (e != null) r += "CheckThread = false: " + e.Message + "; ";
            }
            finally
            {
                env.Dispose();
            }
            env = new LuaEnv(new LuaOptions());
            try
            {
                long used = -1;
                Exception e = OnOtherThread(() =>
                {
                    used = env.MemoryUsed + env.MemoryPeak + env.MemoryLimit + env.InstructionLimit;
                    var time = env.TimeLimit;
                    env.Interrupt();
                });
                if (e != null || used < 0) r += "the statistics from another thread: " + (e == null ? "" + used : e.Message) + "; ";
            }
            finally
            {
                env.Dispose();
            }
            return r;
        }

        // Upstream's LuaBehaviour example: static LuaEnv luaEnv = new LuaEnv(),
        // which Unity may run on a loading thread. The static constructor makes
        // the class initialize on first access, on the thread that reads Env.
        // The env lives for the process: the suite runs FirstUse twice.
        static class StaticEnv
        {
            internal static readonly LuaEnv Env;
            internal static readonly int CreatedOn;

            static StaticEnv()
            {
                CreatedOn = Environment.CurrentManagedThreadId;
                Env = new LuaEnv();
            }
        }

        static LuaEnv MadeOnOtherThread(LuaOptions options)
        {
            LuaEnv made = null;
            Exception e = OnOtherThread(() => made = new LuaEnv(options));
            if (e != null) throw new InvalidOperationException("making the env on another thread: " + e.Message, e);
            return made;
        }

        // The owner is the first thread that uses the env after the constructor
        // (owner decision of 2026-10-28, crash-inventory.md items 5 and 6), not the
        // thread that created it.
        public static string FirstUse()
        {
            string r = "";
            int main = Environment.CurrentManagedThreadId;

            // Created on a worker thread (a static field initializer), then used
            // only on this thread: allowed in every build.
            LuaEnv env = null;
            Exception e = OnOtherThread(() => env = StaticEnv.Env);
            if (e != null) return "the static env on another thread: " + e.Message;
            if (StaticEnv.CreatedOn == main) r += "the static env was made on this thread; ";
            try
            {
                if (Convert.ToInt32(env.DoString("return 1 + 1")[0]) != 2) r += "the static env on the first user; ";
                env.Global.Set("x", 3);
                if (env.Global.Get<int>("x") != 3) r += "the static env's globals; ";
            }
            catch (Exception x)
            {
                r += "the static env made on another thread, used here: " + x.Message + "; ";
            }
            // After this thread's first use, another thread is refused.
            r += Refused("the static env from a second thread", main, () => env.DoString("return 1"));

            // The same with LuaOptions (the core state), and the first use on a
            // third thread: that thread owns it, the creator and this one do not.
            int worker = 0;
            env = MadeOnOtherThread(new LuaOptions());
            e = OnOtherThread(() =>
            {
                worker = Environment.CurrentManagedThreadId;
                env.DoString("function inc(x) return x + 1 end");
            });
            if (e != null) r += "the first use on a third thread: " + e.Message + "; ";
            r += Refused("after a worker's first use", worker, () => env.DoString("return 1"));
            if (Checked())
            {
                try
                {
                    env.DoString("return 1");
                    r += "this thread was not refused after a worker's first use; ";
                }
                catch (InvalidOperationException)
                {
                }
                // Dispose from a thread that does not own the env is refused too.
                try
                {
                    env.Dispose();
                    r += "Dispose was not refused on a thread that does not own the env; ";
                }
                catch (InvalidOperationException)
                {
                }
            }
            // SetOwnerThread hands it over as before.
            env.SetOwnerThread();
            if (Convert.ToInt32(env.DoString("return inc(1)")[0]) != 2) r += "SetOwnerThread after a worker's first use; ";
            env.Dispose();

            // Dispose as the first use, on another thread than the creator's.
            env = MadeOnOtherThread(null);
            try
            {
                env.Dispose();
            }
            catch (Exception x)
            {
                r += "Dispose as the first use: " + x.Message + "; ";
            }

            // SetOwnerThread before any use: that thread owns it, the first user
            // does not take it over.
            env = MadeOnOtherThread(null);
            int handedTo = 0;
            e = OnOtherThread(() =>
            {
                handedTo = Environment.CurrentManagedThreadId;
                env.SetOwnerThread();
                env.DoString("y = 1");
            });
            if (e != null) r += "SetOwnerThread before the first use: " + e.Message + "; ";
            r += Refused("after SetOwnerThread on another thread", handedTo, () => env.DoString("return 1"));
            if (Checked())
            {
                try
                {
                    env.DoString("return 1");
                    r += "this thread took over an env handed to another thread; ";
                }
                catch (InvalidOperationException)
                {
                }
            }
            env.SetOwnerThread();
            env.Dispose();

            // Two threads race for the first use: exactly one wins. Only with the
            // check: without it and without THREAD_SAFE, two threads in one env
            // corrupt it.
            for (int round = 0; round < 10 && Checked(); round++)
            {
                env = MadeOnOtherThread(null);
                int refused = 0, ran = 0;
                var start = new System.Threading.ManualResetEvent(false);
                var racers = new System.Threading.Thread[2];
                for (int i = 0; i < racers.Length; i++)
                {
                    racers[i] = new System.Threading.Thread(() =>
                    {
                        start.WaitOne();
                        try
                        {
                            env.DoString("return 1");
                            System.Threading.Interlocked.Increment(ref ran);
                        }
                        catch (InvalidOperationException)
                        {
                            System.Threading.Interlocked.Increment(ref refused);
                        }
                    });
                    racers[i].Start();
                }
                start.Set();
                foreach (var t in racers) t.Join();
                if (ran != 1 || refused != 1)
                {
                    r += "two threads racing for the first use: " + ran + " ran, " + refused + " refused; ";
                    break;
                }
                env.SetOwnerThread();
                env.Dispose();
            }
            return r;
        }
    }

    // LuaJIT has no limit on nested C calls: Lua -> C# -> Lua -> C# ... ran
    // until the C stack overflowed (SIGSEGV at about 10,240 levels;
    // docs/research/crash-inventory.md, item 7). PUC Lua stops at
    // LUAI_MAXCCALLS with "C stack overflow" when the 199th C# function calls
    // into Lua, and the trampolines now stop LuaJIT at the same depth. The
    // count is per thread, so the check runs on a thread of its own (with room
    // for the frames of 200 levels) where no other C# call is active.
    public static class DeepRecursion
    {
        static int deepest;

        public static int Depth(LuaFunction f, int n)
        {
            if (n > deepest) deepest = n;
            return Convert.ToInt32(f.Call(n)[0]);
        }

        static string recurse(LuaEnv env, string what)
        {
            deepest = 0;
            string got;
            try
            {
                env.DoString("return rec(0)");
                got = "no error";
            }
            catch (LuaException e)
            {
                got = e.Message;
            }
            if (!got.Contains("C stack overflow"))
            {
                return what + ": " + got.Substring(0, Math.Min(300, got.Length)) + "; ";
            }
            return deepest == 199 ? "" : what + ": the error came 199 levels deep on Lua 5.3 to 5.5, here " + deepest + "; ";
        }

        public static string Check()
        {
            string r = null;
            var thread = new System.Threading.Thread(() =>
            {
                try
                {
                    using (var env = new LuaEnv())
                    {
                        env.DoString("function rec(n) return CS.Upstream.DeepRecursion.Depth(rec, n + 1) end");
                        r = recurse(env, "first");
                        // The count went back after the error: the same depth again,
                        // and a recursion below the limit returns.
                        r += recurse(env, "second");
                        env.DoString("function rec50(n) if n == 50 then return n end return CS.Upstream.DeepRecursion.Depth(rec50, n + 1) end");
                        int fifty = Convert.ToInt32(env.DoString("return rec50(0)")[0]);
                        if (fifty != 50) r += "rec50 returned " + fifty + "; ";
                    }
                }
                catch (Exception e)
                {
                    r += e.GetType().Name + ": " + e.Message;
                }
            }, 64 * 1024 * 1024);
            thread.Start();
            thread.Join();
            return r;
        }
    }

    // Lua API calls from C# that raised a Lua error with no handler, or
    // through managed frames (docs/research/crash-inventory.md). With no
    // handler Lua panicked: xLua's panic function threw "unprotected error in
    // call to Lua API" through the native frames (undefined behaviour; Mono
    // happened to unwind them), and from a C# callback the error longjmp'd
    // over the caster's managed frames. Each runs in a LuaEnv of its own.
    public static class UnprotectedRaises
    {
        static string Message(Action action)
        {
            try
            {
                action();
                return "no exception";
            }
            catch (Exception e)
            {
                return e.GetType().Name + ": " + e.Message;
            }
        }

        // LuaTable.ForEach whose action clears the current key and grows the
        // table: the rehash drops the key, and the next step raises "invalid key
        // to 'next'". It now reaches C# as a LuaException from a protected next,
        // as in GetKeys and GetKeys<T>, which take the same step.
        public static string ChangedDuringForEach()
        {
            var env = new LuaEnv();
            try
            {
                env.DoString("t = {} for i = 1, 4 do t['k' .. i] = i end");
                var t = env.Global.Get<LuaTable>("t");
                int n = 0;
                string got = Message(() => t.ForEach<string, int>((k, v) =>
                {
                    t.Set<string, object>(k, null);
                    for (int i = 0; i < 64; i++) t.Set("n" + (n++), i);
                }));
                if (!got.StartsWith("LuaException: ") || !got.Contains("invalid key to 'next'") || got.Contains("unprotected"))
                {
                    return "ForEach: " + got;
                }
                int count = 0;
                t.ForEach<string, object>((k, v) => count++);
                t.Dispose();
                return Convert.ToInt32(env.DoString("return 1 + 1")[0]) == 2 && count > 0 ? "" : "the env does not work afterwards";
            }
            finally
            {
                env.Dispose();
            }
        }

        // A __len metamethod that raises: LuaTable.Length threw from the panic,
        // and a table passed for an int[] or List<int> parameter raised through
        // the caster. LuaJIT reads the raw length (no __len for tables).
        public static string LengthMetamethodError()
        {
            var env = new LuaEnv();
            try
            {
                env.DoString("t = setmetatable({1, 2, 3}, { __len = function() error('len failed') end })");
                var t = env.Global.Get<LuaTable>("t");
                bool jit = env.DoString("return jit ~= nil")[0].Equals(true);
                string got = Message(() => { var n = t.Length; });
                if (jit ? got != "no exception" : (!got.StartsWith("LuaException: ") || !got.Contains("len failed") || got.Contains("unprotected")))
                {
                    return "Length: " + got;
                }
                // A length that is no integer raises too (Lua 5.3+).
                env.DoString("u = setmetatable({}, { __len = function() return 'x' end })");
                got = Message(() => { var n = env.Global.Get<LuaTable>("u").Length; });
                if (!jit && (!got.StartsWith("LuaException: ") || got.Contains("unprotected")))
                {
                    return "Length of a non-integer: " + got;
                }
                // Through a C# callback the error is now a C# exception that the
                // wrapper turns into a Lua error; Lua's own error skipped the caster.
                string array = Convert.ToString(env.DoString(
                    "local ok, e = pcall(CS.Upstream.UnprotectedRaises.Sum, t) return tostring(ok) .. ' ' .. tostring(e)")[0]);
                string list = Convert.ToString(env.DoString(
                    "local ok, e = pcall(CS.Upstream.UnprotectedRaises.Count, t) return tostring(ok) .. ' ' .. tostring(e)")[0]);
                if (jit ? array != "true 6" || list != "true 3"
                    : !array.StartsWith("false ") || !array.Contains("len failed") || !array.Contains("c# exception")
                    || !list.StartsWith("false ") || !list.Contains("len failed") || !list.Contains("c# exception"))
                {
                    return "int[]: " + array + "; List<int>: " + list;
                }
                // Without __len the raw length applies, as before.
                return Convert.ToInt32(env.DoString("return CS.Upstream.UnprotectedRaises.Sum({1, 2, 3})")[0]) == 6 ? "" : "Sum({1, 2, 3}) is not 6";
            }
            finally
            {
                env.Dispose();
            }
        }

        public static int Sum(int[] a)
        {
            int s = 0;
            foreach (var x in a) s += x;
            return s;
        }

        public static int Count(List<int> a)
        {
            return a.Count;
        }

        static LuaEnv current;

        public static void DisposeCurrent()
        {
            current.Dispose();
        }

        // LuaEnv.Dispose from a C# function that Lua called, directly or from a
        // coroutine: lua_close freed the frames the call returned to, and the
        // process aborted. Dispose now throws InvalidOperationException there,
        // and works once the call has returned.
        public static string DisposeWhileRunning()
        {
            var env = new LuaEnv();
            current = env;
            string direct = Message(() => env.DoString("CS.Upstream.UnprotectedRaises.DisposeCurrent()"));
            string coroutine = Message(() => env.DoString(
                "local co = coroutine.create(function() CS.Upstream.UnprotectedRaises.DisposeCurrent() end) "
                + "local ok, e = coroutine.resume(co) if not ok then error(e, 0) end"));
            current = null;
            int after = Convert.ToInt32(env.DoString("return 2 + 3")[0]);
            env.Dispose();
            const string expected = "cannot be disposed while one of its calls runs";
            // The wrapper passes the exception to Lua as an error with its text,
            // which DoString throws as a LuaException.
            if (!direct.Contains(expected)) return "from Lua: " + direct;
            if (!coroutine.Contains(expected)) return "from a coroutine: " + coroutine;
            return after == 5 ? "" : "the env does not work after the refusal";
        }
    }

    // Lua errors raised while C# frames are on the stack. zlua reports SEH
    // crashes on LuaJIT for Win64 when an error unwinds through reverse
    // P/Invoke frames (docs/research/focus-creative-games.md). In xLua C# never
    // raises a Lua error itself: luaL_error and lua_error record it, and the C
    // trampoline raises it after the managed frames have returned
    // (build/xlua_core.c, csharp_function_wrap). A C# exception in a bound
    // method becomes such an error, and a Lua error inside LuaFunction.Call
    // comes back to C# as a LuaException from lua_pcall. Check nests Lua and C#
    // frames, raises in each way, and checks that pcall gets the error and the
    // state still works. windows-host.yml runs it on LuaJIT for Win64 under
    // .NET Framework and Mono (docs/research/windows-host.md).
    public static class CallbackErrors
    {
        public static void Throw(string message)
        {
            throw new InvalidOperationException(message);
        }

        // f(n) from C#: f's Lua error reaches C# as a LuaException, which the
        // bridge passes back to Lua as an error.
        public static object CallLua(LuaFunction f, int n)
        {
            return f.Call(n)[0];
        }

        public static string Handler(string message)
        {
            return "handled: " + message;
        }

        // Builtin loaders (LuaEnv.AddBuildin): C# functions that Lua calls
        // through the trampoline and that raise with LuaAPI.luaL_error and
        // LuaAPI.lua_error.
        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int RaiseString(IntPtr L)
        {
            return XLua.LuaDLL.Bridge.luaL_error(L, "raw luaL_error from C#");
        }

        [MonoPInvokeCallback(typeof(XLua.LuaDLL.lua_CSFunction))]
        static int RaiseNumber(IntPtr L)
        {
            XLua.LuaDLL.Bridge.lua_pushnumber(L, 42);
            return XLua.LuaDLL.Bridge.lua_error(L);
        }

        const string Chunk = @"
            local Errors = CS.Upstream.CallbackErrors
            local failures = {}
            local function expect(ok, err, text, what)
                if ok or not string.find(tostring(err), text, 1, true) then
                    failures[#failures + 1] = what .. ': ' .. tostring(ok) .. ', ' .. string.sub(tostring(err), 1, 200)
                end
            end
            for i = 1, 300 do
                -- LuaJIT's require leaves its loading mark in package.loaded
                -- when the loader raises (loop or previous error loading module).
                package.loaded.raise_string, package.loaded.raise_number = nil, nil
                local ok, err = pcall(require, 'raise_string')
                expect(ok, err, 'raw luaL_error from C#', 'luaL_error')
                ok, err = pcall(require, 'raise_number')
                if ok or err ~= 42 then failures[#failures + 1] = 'lua_error: ' .. tostring(ok) .. ', ' .. tostring(err) end
                ok, err = pcall(Errors.Throw, 'thrown ' .. i)
                expect(ok, err, 'thrown ' .. i, 'exception')
            end
            local function nest(n)
                if n == 0 then Errors.Throw('deep C#') end
                return Errors.CallLua(nest, n - 1)
            end
            local function nestLua(n)
                if n == 0 then error('deep Lua') end
                return Errors.CallLua(nestLua, n - 1)
            end
            for i = 1, 30 do
                local ok, err = pcall(nest, 8)
                expect(ok, err, 'deep C#', 'nested C# error')
                ok, err = pcall(nestLua, 8)
                expect(ok, err, 'deep Lua', 'nested Lua error')
            end
            local resumed, ok, err = coroutine.resume(coroutine.create(function() return pcall(nest, 4) end))
            if not resumed then failures[#failures + 1] = 'resume: ' .. tostring(ok) end
            expect(ok, err, 'deep C#', 'nested error in a coroutine')
            resumed, err = coroutine.resume(coroutine.create(function() Errors.Throw('in a coroutine') end))
            expect(resumed, err, 'in a coroutine', 'resume')
            local xok, msg = xpcall(function() Errors.Throw('xpcall') end, function(m) return Errors.Handler(tostring(m)) end)
            expect(xok, msg, 'xpcall', 'xpcall')
            if string.sub(tostring(msg), 1, 9) ~= 'handled: ' then failures[#failures + 1] = 'handler: ' .. tostring(msg) end
            return table.concat(failures, '; ')";

        public static string Check()
        {
            var env = new LuaEnv();
            try
            {
                env.AddBuildin("raise_string", RaiseString);
                env.AddBuildin("raise_number", RaiseNumber);
                string failures = (string)env.DoString(Chunk, "CallbackErrors")[0];
                if (failures != "") return failures;
                // No pcall in Lua: the error reaches DoString's own lua_pcall,
                // below the C# frame that called it.
                string top = "no exception";
                try
                {
                    env.DoString("CS.Upstream.CallbackErrors.Throw('top level')");
                }
                catch (LuaException e)
                {
                    top = e.Message;
                }
                if (!top.Contains("top level")) return "DoString: " + top;
                return Convert.ToInt32(env.DoString("return 1 + 1")[0]) == 2 ? "" : "the env does not work afterwards";
            }
            finally
            {
                env.Dispose();
            }
        }
    }
}

// Tencent/xLua#1081 and #1179: types whose names are not ASCII. The bridge
// creates a type's metatable with luaL_newmetatable under the type's full name
// (Utils.MetatableKey) and finds it with luaL_getmetatable, which pushes the
// name as UTF-8. On .NET Framework the luaL_newmetatable import passed the name
// in the ANSI code page, so the two names differed (and both types below were
// registered as "Upstream.Utf8Names.?").
namespace Upstream.Utf8Names
{
    public class 甲
    {
        public int Value()
        {
            return 1;
        }
    }

    public class 乙
    {
        public int Value()
        {
            return 2;
        }
    }
}

#if XLUA_GENERAL
// Stand-ins for Unity's types outside Unity, for Tencent/xLua#918
// (Upstream.UnityObjectSlots): ObjectCasters.RefusesTables and both
// generators find UnityEngine.Object by name.
namespace UnityEngine
{
    public class Object
    {
        public string name { get; set; }
    }

    public class GameObject : Object
    {
        public GameObject()
        {
        }

        public GameObject(string name)
        {
            this.name = name;
        }
    }

    public class ScriptableObject : Object
    {
    }

    // As Unity's Component, it cannot be made with new.
    public class Component : Object
    {
        protected Component()
        {
        }
    }
}
#endif
